<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Driver\Batch;

use Override;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetCursor;
use Civi\Lughauth\Shared\Infrastructure\LongTask\TaskContext;
use Civi\Lughauth\Shared\Infrastructure\LongTask\TaskCounterInterface;
use Civi\Lughauth\Shared\Infrastructure\LongTask\TaskReaderInterface;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\List\TemplateSnippetListUsecase;

class TemplateSnippetTaskReader implements TaskReaderInterface, TaskCounterInterface
{
    public function __construct(private readonly TemplateSnippetListUsecase $usecase)
    {

    }
    #[Override]
    public function read(TaskContext $context): array
    {
        $filter = $context->params['filter'];
        $cursor = $context->cursor;
        $result = $this->usecase->list($filter, $cursor ?? new TemplateSnippetCursor(limit: 1));
        $context->cursor = $result->cursor();
        return $result->values();
    }

    #[Override]
    public function expectedTotal(TaskContext $context): int
    {
        $filter = $context->params['filter'];
        return $this->usecase->count($filter);
    }
}
